mapper.select:
		select 	VW_REPAY_WITHOUT_INT.WITHOUT_CASH_ID	cashId,
				VW_REPAY_WITHOUT_INT.WITHOUT_BRANCH 	branch,
				PTL_RECE_POSITION.AMOUNT				amount,
				PTL_RECE_POSITION.REC_TYPE  			recType,
				FIN_TRADE_PRODUCT.VDATE					vdate,
				FIN_TRADE_PRODUCT.MDATE					mdate
		    from VW_REPAY_WITHOUT_INT,PTL_RECE_POSITION,FIN_TRADE_PRODUCT
		    where VW_REPAY_WITHOUT_INT.BRANCH = #{libranch}
		    and  VW_REPAY_WITHOUT_INT.WITHOUT_BRANCH = PTL_RECE_POSITION.BRANCH
		    and VW_REPAY_WITHOUT_INT.FINPRODID = PTL_RECE_POSITION.FINPROD_ID
		    and VW_REPAY_WITHOUT_INT.WITHOUT_BRANCH =FIN_TRADE_PRODUCT.BRANCH
		    AND VW_REPAY_WITHOUT_INT.FINPRODID =FIN_TRADE_PRODUCT.FINPROD_ID
		    and PTL_RECE_POSITION.FINPROD_ID = #{finprodId}
		    and PTL_RECE_POSITION.PORTFOLIO_ID =#{portfolioId}
		    and PTL_RECE_POSITION.HODING_TYPE = #{POSITION_TYPE_03}
		    and PTL_RECE_POSITION.CDATE= #{Cdate}

    			and PTL_RECE_POSITION.INV_AIM = #{invAim}


    			and PTL_RECE_POSITION.SEC_ACCT_ID= #{secAcctId}

	select CASH_ID 		cashId,
		   CASH_TYPE  	cashType
	 from FIN_CASH_PLAN


			and mdate = #{mdate}


			and FINPROD_ID = #{finprodId}


			and BRANCH = #{branch}


            AND CASH_TYPE IN

                ${item}
